from agent import *from models.products import *def run(context: dict[str, str], session: Session):    session.queue(Request("https://www.ecoustics.com/reviews"), process_productlist, dict())def process_productlist(data: Response, context: dict[str, str], session: Session):    prods = data.xpath("//div[@id='zox-main-blog-wrap']//div[contains(@class, 'zox-main-blog')]//div[@class='zox-art-title']")    for prod in prods:        name = prod.xpath("h2/text()").string()        url = prod.xpath("a/@href").string()        session.queue(Request(url), process_product, dict(name=name, url=url))    pages = data.xpath("//div[@class='pagination']/a")    for page in pages:        url = page.xpath("@href").string()        session.queue(Request(url), process_productlist, dict(context))def process_product(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name'].split(' Review')[0]    product.ssid = context['url'].split('/')[-2]    product.category = data.xpath("//span[@class='zox-post-cat']//text()").string()    product.url = context['url']    if 'Reviews' not in product.category:        product.manufacturer = product.category    review = Review()    review.title = context['name']    review.type = 'pro'    review.date = data.xpath("//span[contains(@class, 'zox-post-date')]//text()").string()    review.url = context['url']    review.ssid = product.ssid    author_name = data.xpath("//span[contains(@class, 'zox-author-name')]/a/text()").string()    profile_url = data.xpath("//span[contains(@class, 'zox-author-name')]/a/@href").string()    review.authors.append(Person(name=author_name, ssid=author_name, profile_url=profile_url))    summary = data.xpath("//div[@class='zox-post-head zoxrel']//span[@class='zox-post-excerpt']//text()").string(multiple=True)    if summary:        review.properties.append(ReviewProperty(type='summary', value=summary))    conclusion = data.xpath("//h3[text()='Conclusion']//following::p[1]//text()").string(multiple=True)    if conclusion:        review.properties.append(ReviewProperty(type='conclusion', value=conclusion))    excerpt = data.xpath("//div[contains(@class, 'zox-post-body-wrap')]//div[@class='zox-post-body left zoxrel zox100']//text()").string(multiple=True)    crit_title = data.xpath("//h3[@class='critic-review-title']//text()").string(multiple=True)    crit = data.xpath("//h3[@class='critic-review-title']//following-sibling::*//text()").string(multiple=True)    if excerpt:        if crit and crit_title:             excerpt = excerpt.replace(crit_title, '')            excerpt = excerpt.replace(crit, '')        if summary:            excerpt = excerpt.replace(summary, '')        if conclusion:            excerpt = excerpt.replace(conclusion, '')        excerpt = excerpt.strip().replace('. Conclusion', '.')        review.properties.append(ReviewProperty(type='excerpt', value=excerpt))    if summary or conclusion or excerpt:        product.reviews.append(review)        session.emit(product)